/* GENERATED by gen_hcon_augmented.py -- models are generated.
   SAT_ASSESSMENT_FRAUD_INVESTIGATION
   *** UNRATIFIED. This payload is a BUILD-SIDE PROPOSAL from the map's
   augmentation blocks and has NOT been ratified by the modeller. Attributes here
   are not declared on this satellite in data_7.js. Do not treat it as part of the
   ratified vault. ***
   anchor      : HUB_ASSESSMENT   (kind: hub, origin: map.anchor)
   track       : unratified
   history     : SCD2
   feeders     : 1 emitted of 1 (one per source view AND run)
   runs        : 1 -- opus_health_delta3
   payload     : 1 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_ASSESSMENT_HK
   hashdiff    : SAT_ASSESSMENT_FRAUD_INVESTIGATION_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
*/

with feeders as (
    select
        md5(upper('HUB_ASSESSMENT|' || (HUB_ASSESSMENT_BK__CONTRACT_ID_CLAIM_ID_RISK_ID))) as HUB_ASSESSMENT_HK
        , RISK_SUSP_FRAUD_ID as SUSPECTED_FRAUD_SCENARIO_REFERENCE
        , 'BJAZ_RISK_TRANS_DTLS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_risk_trans_dtls') }}
    where (md5(normalise(upper(nullif(coalesce(nullif(trim(CONTRACT_ID),''),'') || '|' || coalesce(nullif(trim(CLAIM_ID),''),'') || '|' || coalesce(nullif(trim(RISK_ID),''),''), '||'))))) is not null
),

resolved as (
    select
        HUB_ASSESSMENT_HK,
        max(case when SOURCE_RUN = 'opus_health_delta3' then SUSPECTED_FRAUD_SCENARIO_REFERENCE end) as SUSPECTED_FRAUD_SCENARIO_REFERENCE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_ASSESSMENT_HK
),

hashed as (
    select
        *,
        case when SUSPECTED_FRAUD_SCENARIO_REFERENCE is not null
                     then md5(upper(coalesce(cast(SUSPECTED_FRAUD_SCENARIO_REFERENCE as varchar), '')))
                end as SAT_ASSESSMENT_FRAUD_INVESTIGATION_HASHDIFF
    from resolved
)

select * from hashed
where HUB_ASSESSMENT_HK is not null
  and SAT_ASSESSMENT_FRAUD_INVESTIGATION_HASHDIFF is not null
